// Regenerates src/components/brand-icons.ts and social-icons.ts from simple-icons.
// Importing `simple-icons` at runtime pulls its 12 MB barrel into the dev
// server, so the app imports this tiny generated file instead.
// Usage: bun scripts/gen-brand-icons.mjs
import { writeFileSync } from 'node:fs'
import * as si from 'simple-icons'

const brands = [
  'siBitbucket',
  'siClaude',
  'siCloudflare',
  'siCodeberg',
  'siCoderabbit',
  'siCursor',
  'siForgejo',
  'siGitea',
  'siGithub',
  'siGitlab',
  'siLinear',
  'siQodo',
  'siSentry',
  'siVercel',
]
// The footer shows these on every page, so they live apart from the brand
// logos and the shared header chunk stays small.
const socials = ['siDiscord', 'siGithub', 'siX', 'siYoutube']

const banner = `// Generated by scripts/gen-brand-icons.mjs from simple-icons (CC0). Do not edit.
export type BrandIcon = { title: string; hex: string; path: string }

`
function write(file, names) {
  let out = banner
  for (const name of names) {
    const i = si[name]
    if (!i) throw new Error(`missing ${name}`)
    out += `export const ${name}: BrandIcon = ${JSON.stringify({ title: i.title, hex: i.hex, path: i.path })}\n`
  }
  writeFileSync(new URL(`../src/components/${file}`, import.meta.url), out)
  console.log(`wrote ${names.length} icons to ${file}`)
}
write('brand-icons.ts', brands)
write('social-icons.ts', socials)
